import { ROOM_TEMPLATES, ROOM_WIDTH } from './roomTemplates.js';

function hashSeed(seed, index) {
  let h = 2166136261;
  const text = `${String(seed)}:${index}`;
  for (let i = 0; i < text.length; i += 1) h = Math.imul(h ^ text.charCodeAt(i), 16777619);
  return h >>> 0;
}

/** Five reusable static-body sets; no object destruction during room travel. */
export default class LevelGenerator {
  constructor(scene, { seed = 1 } = {}) {
    this.scene = scene;
    this.seed = seed;
    this.pool = new Map();
    this.activeIndex = null;
    this.doorY = null;
  }

  enterRoom(index, entryDoorY = 900) {
    if (!Number.isSafeInteger(index)) throw new TypeError('Room index must be a safe integer');
    if (!Number.isFinite(entryDoorY) || entryDoorY < 150 || entryDoorY > 910) {
      throw new RangeError('Door centre must be within 150..910');
    }
    // A single continuous door elevation is part of this run's generation parameters.
    // Reject inconsistent callers rather than silently disconnecting a previously visited room.
    if (this.doorY !== null && entryDoorY !== this.doorY) {
      throw new RangeError('Pass the previous room door.y when travelling');
    }
    this.doorY = entryDoorY;
    for (const room of this.pool.values()) this._setEnabled(room, false);
    let room = this.pool.get(index);
    if (!room) {
      if (this.pool.size === 5) {
        const victim = [...this.pool.keys()].find((key) => key !== this.activeIndex);
        room = this.pool.get(victim);
        this.pool.delete(victim);
      } else {
        const solids = this.scene.physics.add.staticGroup();
        // Six boundary rectangles and at most three platforms in every prefab.
        const pieces = Array.from({ length: 9 }, () => {
          // Render the collider itself: decorative furniture is background art,
          // not a reliable indication of the walkable or web-attachable bounds.
          const object = this.scene.add.rectangle(0, 0, 1, 1, 0x263747, 1)
            .setStrokeStyle(2, 0x8296a3, 1).setDepth(-20);
          solids.add(object);
          return object;
        });
        room = { solids, pieces };
      }
      this._configure(room, index);
      this.pool.set(index, room);
    }
    this._setEnabled(room, true);
    this.activeIndex = index;
    return room;
  }

  _configure(room, index) {
    const template = ROOM_TEMPLATES[hashSeed(this.seed, index) % ROOM_TEMPLATES.length];
    const y = this.doorY;
    const upper = y - 90 - 60;
    // Ground-level exits must reach the floor: no 10px sill blocking the spider.
    const doorBottom = y >= 900 ? 1000 : y + 90;
    const lower = 1000 - doorBottom;
    const rectangles = [
      [960, 30, 1920, 60], [960, 1040, 1920, 80],
      [8, 60 + upper / 2, 16, upper], [1912, 60 + upper / 2, 16, upper],
      [8, doorBottom + lower / 2, 16, lower], [1912, doorBottom + lower / 2, 16, lower],
      ...template.platforms.map((p) => [p.x + p.width / 2, p.y, p.width, 24]),
    ];
    room.pieces.forEach((object, i) => {
      const r = rectangles[i];
      object.roomUsed = Boolean(r && r[3] > 0);
      object.spiderPlatform = i >= 6;
      if (object.roomUsed) {
        object.setPosition(r[0], r[1]).setSize(r[2], r[3]);
        // Rectangles are not Arcade Images: update the StaticBody explicitly.
        object.body.setSize(r[2], r[3]);
        object.body.updateFromGameObject();
      }
    });
    // Keep the armed shelf above the giant's standing head, not intersecting his torso.
    const sourceShelf = template.decorations.find((d) => d.kind === 'shelf');
    const shelf = { ...sourceShelf, y: Math.min(sourceShelf.y, 400) };
    Object.assign(room, {
      index, templateId: template.id,
      decorations: template.decorations.map((d) => ({ ...(d.kind === 'shelf' ? shelf : d) })),
      shadowZones: template.shadows.map((z) => ({ ...z })),
      memorySpawns: template.memories.map((p) => ({ ...p })),
      humanSpawn: { x: 960, y: 760 },
      waypoints: [{ x: 260, y: 1000 }, { x: 1660, y: 1000 }],
      doors: { left: { x: 0, y }, right: { x: ROOM_WIDTH, y } },
      shelf: { ...shelf, anchor: { x: shelf.x - shelf.width / 2, y: shelf.y - 40 } },
    });
  }

  _setEnabled(room, enabled) {
    for (const object of room.pieces) {
      const active = enabled && object.roomUsed;
      object.setActive(active).setVisible(active);
      object.body.enable = active;
    }
  }

  dispose() {
    for (const room of this.pool.values()) room.solids.clear(true, true);
    for (const room of this.pool.values()) room.solids.destroy();
    this.pool.clear();
    this.activeIndex = null;
    this.doorY = null;
  }
}

