import Phaser from 'phaser'
import Spider from '../actors/Spider.js'
import Human from '../systems/Human.js'
import LevelGenerator from '../systems/LevelGenerator.js'
import Progression from '../systems/Progression.js'
import { createPresentation } from '../visual/Presentation.js'
import AudioDirector from '../audio/AudioDirector.js'

export default class GameScene extends Phaser.Scene {
  constructor() { super('GameScene') }
  create({ attempt = 1 } = {}) {
    this.cleaned = false
    this.physics.resume()
    this.cameras.main.resetFX()
    this.progression = new Progression(this)
    this.progression.attempt = attempt
    this.collected = new Set()
    this.roomIndex = 0
    this.lastDamage = -2000
    this.lastBite = -2000
    this.lastVacuum = 0
    this.roomLock = 0
    this.ended = false
    this.generator = new LevelGenerator(this, { seed: 241031 })
    this.presentation = createPresentation(this)
    this.audioDirector = new AudioDirector(this)
    this.room = this.generator.enterRoom(0, 900)
    this.spider = new Spider(this, 150, 940, { solids: null })
    this.spider.setCollideWorldBounds(false)
    this.memoryGroup = this.physics.add.staticGroup()
    this.vacuum = this.add.rectangle(-200, 955, 90, 55, 0x9f3842)
    this.physics.add.existing(this.vacuum)
    this.vacuum.body.setAllowGravity(false).setImmovable(true)
    this.vacuum.setVisible(false); this.vacuum.body.enable = false
    this.vacuumOverlap = this.physics.add.overlap(this.spider, this.vacuum, () => this.damage({ amount: 12, source: 'vacuum' }))
    this.shelfGraphics = this.add.graphics().setDepth(4)
    this.hint = this.add.text(960, 155, '', { fontSize: '25px', color: '#f5d4c1', align: 'center', backgroundColor: '#131524bb', padding: { x: 12, y: 7 } }).setOrigin(.5).setDepth(20)
    this.cutKey = this.input.keyboard.addKey('E')
    this.menuKey = this.input.keyboard.addKey('ESC')
    this.bindRoom()
    this.handlers = {
      'jam:step': ({ actor }) => { if (actor === 'human' && !this.ended) this.cameras.main.shake(200, .003) },
      'jam:damage': payload => this.damage(payload),
      'jam:bite': payload => this.bite(payload),
      'jam:alert': ({ state }) => { this.progression.alert = state; this.publish() },
      'jam:restart': () => { const attempt = this.progression.getSnapshot().attempt + 1; this.cleanup(); this.scene.restart({ attempt }) },
      'jam:menu': () => { this.cleanup(); this.scene.start('MenuScene') },
    }
    for (const [event, handler] of Object.entries(this.handlers)) this.game.events.on(event, handler)
    this.scene.launch('UIScene')
    this.events.once('shutdown', this.cleanup, this)
    this.publish()
  }
  bindRoom() {
    this.playerCollider?.destroy(); this.humanCollider?.destroy(); this.biteOverlap?.destroy(); this.memoryOverlap?.destroy()
    if (this.human) this.human.dispose()
    this.spider.solids = this.room.solids
    this.playerCollider = this.physics.add.collider(this.spider, this.room.solids)
    const spawn = this.room.humanSpawn
    this.human = new Human(this, spawn.x, spawn.y, {
      spider: this.spider, solids: this.room.solids, waypoints: this.room.waypoints,
      progression: this.progression, shadowZones: this.room.shadowZones,
    })
    this.progression.alert = 'PATROL'
    this.humanCollider = this.physics.add.collider(this.human, this.room.solids, () => {
      if (this.human.body.blocked.left || this.human.body.blocked.right) this.human.collideWithObstacle()
    }, (_, surface) => !surface.spiderPlatform)
    // Raised spider ledges are in the foreground lane; the giant patrols behind them.
    this.biteOverlap = this.physics.add.overlap(this.spider, this.human, () => {
      if (this.spider.body.velocity.y > 90 && this.spider.y < this.human.y) {
        this.bite({ x: this.spider.x, y: this.spider.y, damage: 25 })
        this.spider.setVelocityY(-330)
      }
    })
    this.memoryGroup.clear(true, true)
    this.room.memorySpawns.forEach((point, index) => {
      const id = `${this.roomIndex}:${index}`
      if (this.collected.has(id)) return
      const fragment = (this.textures.exists('art2d-memory')
        ? this.add.image(point.x, point.y, 'art2d-memory').setDisplaySize(64, 64)
        : this.add.circle(point.x, point.y, 17, 0xf6d7a0)).setDepth(6)
      this.physics.add.existing(fragment, true)
      // Glow is larger than the original collectible; keep its 34×34 pickup bounds.
      fragment.body.setSize(34, 34)
      fragment.memoryId = id
      this.memoryGroup.add(fragment)
      this.tweens.add({ targets: fragment, alpha: .45, duration: 900, yoyo: true, repeat: -1 })
    })
    this.memoryOverlap = this.physics.add.overlap(this.spider, this.memoryGroup, (_, fragment) => {
      if (this.ended || this.collected.has(fragment.memoryId)) return
      this.collected.add(fragment.memoryId)
      this.progression.collectMemory(fragment.memoryId)
      fragment.destroy()
      this.spider.setWebUnlocked(this.progression.getSnapshot().webUnlocked)
      this.publish()
    })
    this.presentation.applyRoom(this.room)
    this.vacuum.setVisible(false); this.vacuum.body.enable = false
    this.shelfFalling = false
    this.publish()
  }
  damage({ amount, source }) {
    if (this.ended || this.time.now - this.lastDamage < 1100) return
    if (source === 'human' && this.progression.getSnapshot().act === 1) return
    this.lastDamage = this.time.now
    this.progression.damage(amount)
    this.spider.health = this.progression.getSnapshot().health
    this.cameras.main.shake(180, .008)
    this.publish()
  }
  bite({ x, y, damage = 25 }) {
    if (this.ended || this.time.now - this.lastBite < 600 || Phaser.Math.Distance.Between(x, y, this.human.x, this.human.y) > 400) return
    this.lastBite = this.time.now
    this.human.hit(damage)
    this.audioDirector.tone(180, .12, .08, x)
  }
  publish() {
    const snapshot = this.progression.getSnapshot()
    this.presentation?.setState(snapshot)
    this.game.events.emit('jam:state', { ...snapshot })
    if (snapshot.status !== 'playing' && !this.ended) {
      this.ended = true
      this.physics.pause()
      this.spider.setVelocity(0, 0)
      this.human.setVelocity(0, 0)
      this.cameras.main.fade(650, 8, 4, 12, false)
      // HUD lives on its own camera, so fading the world keeps result buttons interactive.
    }
  }
  changeRoom(direction) {
    if (this.time.now < this.roomLock || this.shelfFalling) return
    // Release the old room's tether and ceiling gravity before teleporting.
    this.spider.setWebUnlocked(false)
    this.spider.ceilingAttached = false
    this.spider.body.setGravityY(0).setAcceleration(0, 0)
    this.spider.setFlipY(false).setAngle(0)
    this.spider.setWebUnlocked(this.progression.getSnapshot().webUnlocked)
    this.roomLock = this.time.now + 700
    this.roomIndex += direction
    this.room = this.generator.enterRoom(this.roomIndex, this.room.doors[direction > 0 ? 'right' : 'left'].y)
    this.spider.setPosition(direction > 0 ? 90 : 1830, this.room.doors.left.y)
    this.spider.setVelocity(0, 0)
    this.bindRoom()
  }
  update(time, delta) {
    if (!this.progression) return
    if (Phaser.Input.Keyboard.JustDown(this.menuKey)) { this.game.events.emit('jam:menu'); return }
    if (this.ended) return
    this.spider.update(time, delta)
    this.human.update(time, delta)
    this.presentation.update(time, delta)
    if (this.spider.x > 1900) this.changeRoom(1)
    else if (this.spider.x < 20) this.changeRoom(-1)
    if (this.spider.y > 1160) this.damage({ amount: 100, source: 'vacuum' })
    const state = this.progression.getSnapshot()
    if (state.act >= 2 && time - this.lastVacuum > 12500) {
      this.lastVacuum = time
      const fromLeft = this.spider.x > 960
      this.vacuum.setPosition(fromLeft ? 50 : 1870, 955).setVisible(true)
      this.vacuum.body.enable = true
      this.vacuum.body.setVelocityX(fromLeft ? 220 : -220)
      this.game.events.emit('jam:noise', { x: this.vacuum.x, y: 955, radius: 1600 })
    }
    if (this.vacuum.visible) {
      if (Math.abs(this.spider.x - this.vacuum.x) < 280 && this.spider.y > 850) this.spider.body.velocity.x += Math.sign(this.vacuum.x - this.spider.x) * delta * .12
      if (this.vacuum.x < -100 || this.vacuum.x > 2020) { this.vacuum.setVisible(false); this.vacuum.body.enable = false }
    }
    const shelf = this.room.shelf
    this.shelfGraphics.clear()
    if (state.act === 3) {
      const shelfY = this.shelfFalling ? Math.min(1000, shelf.y + (time - this.shelfFallAt) * 1.5) : shelf.y
      if (this.shelfFalling && !this.shelfResolved) {
        const body = this.human.body
        const overlapsX = body.right > shelf.x - shelf.width / 2 && body.left < shelf.x + shelf.width / 2
        // Swept contact prevents fast frames from skipping the target.
        if (overlapsX && shelfY + shelf.height >= body.top && this.shelfPreviousY <= body.bottom) {
          this.shelfResolved = true
          this.human.fall()
          this.progression.cutShelf({ humanUnderShelf: true })
          this.cameras.main.shake(220, .018)
          this.publish()
        } else if (shelfY >= 1000) {
          this.shelfFalling = false // A miss can be retried rather than soft-locking the run.
        }
        this.shelfPreviousY = shelfY
      }
      this.shelfGraphics.lineStyle(3, 0xddd2c8).lineBetween(shelf.anchor.x, shelf.anchor.y, shelf.x, shelfY)
      this.shelfGraphics.fillStyle(0x713d3c).fillRect(shelf.x - shelf.width / 2, shelfY, shelf.width, shelf.height)
      // The murder weapon is visibly carried down by the shelf, not only mentioned in text.
      this.shelfGraphics.fillStyle(0x987858).fillRect(shelf.x - 5, shelfY - 48, 10, 48)
      this.shelfGraphics.fillStyle(0xd3d4d6).fillRect(shelf.x - 30, shelfY - 58, 60, 20)
      this.hint.setText('Молоток на полке — орудие гибели твоей семьи. Заманите человека под полку.\nE рядом с нитью — перерезать крепление; упавший молоток завершит месть.')
      const nearThread = Phaser.Math.Distance.Between(this.spider.x, this.spider.y, shelf.anchor.x, shelf.anchor.y) < 360
      if (Phaser.Input.Keyboard.JustDown(this.cutKey) && nearThread && !this.shelfFalling) {
        const under = Math.abs(this.human.x - shelf.x) < shelf.width / 2 + 50
        if (under) {
          this.shelfFalling = true; this.shelfFallAt = time
          this.shelfPreviousY = shelf.y; this.shelfResolved = false
        } else this.hint.setText('Слишком рано: человек должен оказаться под полкой.')
      }
    } else this.hint.setText(state.act === 1 ? 'Пробуждение · соберите 3 фрагмента памяти. Пока человек не атакует.' : 'Охота · ещё 10 фрагментов. Прячьтесь в тени; опасайтесь пылесоса.')
  }
  cleanup() {
    if (this.cleaned) return
    this.cleaned = true
    for (const [event, handler] of Object.entries(this.handlers || {})) this.game.events.off(event, handler)
    this.spider?.dispose(); this.human?.dispose()
    this.presentation?.destroy(); this.audioDirector?.destroy(); this.generator?.dispose()
    this.scene.stop('UIScene')
  }
}

