import test from 'node:test';
import assert from 'node:assert/strict';
import Progression from '../src/jam2d/systems/Progression.js';
import LevelGenerator from '../src/jam2d/systems/LevelGenerator.js';

test('Jam2D: unique memories, 3/13 thresholds, gated finale, death and restart', () => {
  const p = new Progression(null);
  assert.equal(p.cutShelf({ humanUnderShelf: true }), false);
  for (let i = 0; i < 3; i++) p.collectMemory(i);
  assert.equal(p.collectMemory(2), false);
  assert.equal(p.getSnapshot().act, 2);
  assert.equal(p.getSnapshot().webUnlocked, true);
  for (let i = 3; i < 12; i++) p.collectMemory(i);
  assert.equal(p.getSnapshot().act, 2);
  p.collectMemory(12);
  assert.equal(p.getSnapshot().act, 3);
  assert.equal(p.cutShelf({ humanUnderShelf: false }), false);
  assert.equal(p.cutShelf({ humanUnderShelf: true }), true);
  p.restart();
  assert.equal(p.getSnapshot().attempt, 2);
  assert.equal(p.getSnapshot().memories, 0);
  p.damage(100);
  assert.equal(p.getSnapshot().status, 'dead');
  assert.equal(p.collectMemory('late'), false);
});

test('Jam2D: 400 room transitions reuse at most five connected body sets', () => {
  let created = 0;
  const scene = { add: { rectangle(x, y, width, height, fillColor, fillAlpha) { return {
    fillColor, fillAlpha,
    body: { setSize(w, h) { this.width = w; this.height = h; }, updateFromGameObject() {} },
    setPosition(x, y) { this.x = x; this.y = y; return this; },
    setSize(w, h) { this.width = w; this.height = h; return this; },
    setStrokeStyle(width, color, alpha) { this.strokeAlpha = alpha; return this; },
    setDepth(depth) { this.depth = depth; return this; },
    setActive(value) { this.active = value; return this; },
    setVisible(value) { this.visible = value; return this; },
  }; } }, physics: { add: { staticGroup() {
    created++;
    return { add() {}, clear() {}, destroy() {} };
  } } } };
  const generator = new LevelGenerator(scene, { seed: 241031 });
  for (const i of [...Array(200).keys(), ...Array(200).keys()].map((i, n) => n < 200 ? i : 199 - i)) {
    const room = generator.enterRoom(i, 900);
    assert.equal(room.doors.left.y, 900);
    assert.equal(room.doors.right.y, 900);
    assert.ok(generator.pool.size <= 5);
    assert.ok(room.pieces.some(p => p.body.enable));
    for (const cached of generator.pool.values()) {
      for (const piece of cached.pieces) {
        assert.equal(piece.visible, piece.body.enable);
        assert.equal(piece.active, piece.body.enable);
        if (!piece.body.enable) continue;
        assert.equal(piece.fillAlpha, 1, 'every enabled collider has an opaque surface');
        assert.equal(piece.strokeAlpha, 1, 'collision edge remains readable');
        assert.ok(piece.depth > -30 && piece.depth < 0, 'surface above decor, below actors');
        assert.equal(piece.width, piece.body.width);
        assert.equal(piece.height, piece.body.height);
      }
    }
  }
  assert.equal(created, 5);
  assert.throws(() => generator.enterRoom(1, 850), RangeError);
  generator.dispose();
});

